async def act(page):
    # Plan:
    # 1) Go to Manage Products using a relative goto
    # 2) Click Add Product
    # 3) If attribute-set / product-type step appears, choose reasonable defaults and continue
    # 4) Fill Name, Price, Color, Size
    # 5) Open Inventory tab, set Qty=42 and ensure In Stock
    # 6) Save (make this the last action since it will navigate away)

    # Reason: use relative navigation when possible and be defensive about selectors.

    # Navigate to Manage Products
    await page.goto('/index.php/admin/catalog_product/')
    await page.wait_for_load_state('networkidle')

    # Click "Add Product" (try several approaches)
    try:
        await page.get_by_role('button', name='Add Product').click()
    except Exception:
        try:
            # fallback to any element with visible text
            await page.get_by_text('Add Product').click()
        except Exception:
            # last resort: click a link with that name
            try:
                await page.get_by_role('link', name='Add Product').click()
            except Exception:
                pass

    # Wait a short time for the product creation UI to appear
    await page.wait_for_timeout(800)

    # If there's an Attribute Set combobox, choose Default
    try:
        await page.get_by_role('combobox', name='Attribute Set').select_option(label='Default')
    except Exception:
        # ignore if not present
        pass

    # If there's a Simple Product radio button, choose it
    try:
        await page.get_by_role('radio', name='Simple Product').check()
    except Exception:
        pass

    # If there's a Continue or Next button to proceed to the product form, click it
    try:
        await page.get_by_role('button', name='Continue').click()
    except Exception:
        try:
            await page.get_by_text('Continue').click()
        except Exception:
            pass

    # Wait for product form to render
    await page.wait_for_timeout(1000)

    # Fill product Name (be defensive and try multiple possible labels)
    product_name_label = None
    for label in ('Name', 'Product Name'):
        try:
            await page.get_by_label(label).wait_for(timeout=3000)
            product_name_label = label
            break
        except Exception:
            continue

    if product_name_label:
        await page.get_by_label(product_name_label).fill('FancyBoy Man Causal Jeans')
    else:
        # fallback: try the first textbox on the page
        try:
            await page.get_by_role('textbox').first.fill('FancyBoy Man Causal Jeans')
        except Exception:
            pass

    # Fill Price
    try:
        await page.get_by_label('Price').fill('169.99')
    except Exception:
        try:
            await page.get_by_label('Product Price').fill('169.99')
        except Exception:
            # try to find a textbox that looks like price (last resort)
            try:
                # find inputs that contain 'price' in the accessible name
                price_input = page.get_by_role('textbox').filter(has_text='Price')
                await price_input.first.fill('169.99')
            except Exception:
                pass

    # Select Color = Blue
    try:
        await page.get_by_role('combobox', name='Color').select_option(label='Blue')
    except Exception:
        try:
            await page.get_by_label('Color').select_option(label='Blue')
        except Exception:
            try:
                await page.get_by_label('Color').fill('Blue')
            except Exception:
                pass

    # Select Size = 34
    try:
        await page.get_by_role('combobox', name='Size').select_option(label='34')
    except Exception:
        try:
            await page.get_by_label('Size').select_option(label='34')
        except Exception:
            try:
                await page.get_by_label('Size').fill('34')
            except Exception:
                pass

    # Go to Inventory tab to set quantity
    try:
        await page.get_by_role('tab', name='Inventory').click()
    except Exception:
        try:
            await page.get_by_text('Inventory').click()
        except Exception:
            pass

    # Wait briefly for Inventory fields to render
    await page.wait_for_timeout(500)

    # Set Qty = 42 (try common labels)
    qty_set = False
    for qty_label in ('Qty', 'Quantity'):
        try:
            await page.get_by_label(qty_label).fill('42')
            qty_set = True
            break
        except Exception:
            continue

    if not qty_set:
        # fallback: try first numeric textbox
        try:
            # find textbox and fill, but avoid overwriting name/sku fields by checking current value
            txts = page.get_by_role('textbox')
            await txts.nth(0).fill('42')
        except Exception:
            pass

    # Ensure stock availability is In Stock
    try:
        await page.get_by_role('combobox', name='Stock Availability').select_option(label='In Stock')
    except Exception:
        try:
            await page.get_by_role('radio', name='In Stock').check()
        except Exception:
            try:
                await page.get_by_label('Stock Availability').select_option(label='In Stock')
            except Exception:
                pass

    # Save product (this will navigate away; make it the last action)
    try:
        await page.get_by_role('button', name='Save').click()
    except Exception:
        try:
            await page.get_by_text('Save').click()
        except Exception:
            # last resort: press Enter in case save is a form submission
            try:
                await page.keyboard.press('Enter')
            except Exception:
                pass

