    try:
        await page.get_by_role('radio', name='Simple Product').check()
    except Exception:
        pass

    # If there's a Continue or Next button to proceed to the product form, click it
    try:
        await page.get_by_role('button', name='Continue').click()
    except Exception:
        try:
            await page.get_by_text('Continue').click()
        except Exception:
            pass

    # Wait for product form to render
    await page.wait_for_timeout(1000)

